func (q *Queries) GetQuizQuestionsByLesson(ctx context.Context, arg GetQuizQuestionsByLessonParams) ([]LessonQuiz, error) {
	rows, err := q.db.Query(ctx, getQuizQuestionsByLesson, arg.LessonID, arg.TenantID)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []LessonQuiz
	for rows.Next() {
		var i LessonQuiz
		if err := rows.Scan(
			&i.ID,
			&i.TenantID,
			&i.LessonID,
			&i.Question,
			&i.Options,
			&i.Answer,
			&i.Explanation,
			&i.Position,
			&i.CreatedAt,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

